class Usage(StrictBase):
    """
    Disjoint token categories. input_tokens is the total input including cache reads and writes; cached_input_tokens (reads) and cache_write_input_tokens are parts of it. output_tokens includes reasoning_tokens. Cost is computed from the disjoint categories: uncached input, cache reads, cache writes, output.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    input_tokens: Annotated[StrictInt, Field(ge=0)]
    output_tokens: Annotated[StrictInt, Field(ge=0)]
    cached_input_tokens: Annotated[StrictInt, Field(ge=0)]
    cache_write_input_tokens: Annotated[
        StrictInt,
        Field(description="Input tokens written to the provider prompt cache (billed at the write rate).", ge=0),
    ]
    cost_usd: Annotated[StrictFloat, Field(ge=0.0)]
    cost_estimated: StrictBool
    reasoning_tokens: Annotated[
        StrictInt, Field(description="Part of output_tokens spent on reasoning (billed as output).", ge=0)
    ]
    tokens_estimated: Annotated[
        StrictBool,
        Field(
            description="True when the provider returned no usage (a cancelled call) and the counts are Noema's estimate. Missing provider usage is not zero usage."
        ),
    ]


