type TurnEvent = Annotated[
    TurnCreatedEvent | PreflightCompletedEvent | RouteSelectedEvent | DecisionCompletedEvent | DecisionUpdatedEvent | RouteConfirmedEvent | GenerationStartedEvent | GenerationDeltaEvent | GenerationCommittedEvent | GenerationCancelledEvent | GenerationReroutedEvent | GenerationCompletedEvent | TurnVerifiedEvent | TurnCompletedEvent | ErrorEvent,
    Field(
        description="One SSE `data:` payload. Each frame is `id: <n>` (monotonic per turn), `event: <type>` and one line of\n`data: <JSON>`. A `: ping` comment is sent whenever no frame was written for 15 s. Clients ignore unknown event types.\n",
        discriminator="type",
    ),
]
